import { describe, expect, it, vi } from 'vitest';
import { installFetchPatch } from './fetchPatch';
import { createGate } from './gate';
import type { Mock } from '../core/types';

const settings = { enabled: true, recording: true };

function makeWin() {
  const nativeFetch = vi.fn(async (_input: unknown, _init?: RequestInit) => new Response('real'));
  const win = {
    fetch: nativeFetch,
    Request,
    Response,
    Headers,
    location: { href: 'https://app.test/page' },
  } as unknown as Window;
  return { win, nativeFetch };
}

function mockFor(urlPattern: string, method: Mock['method'] = 'GET'): Mock {
  return {
    id: 'm1', enabled: true, method, urlPattern, source: 'manual', createdAt: 1,
    response: { status: 200, headers: {}, body: 'mocked', bodyEncoding: 'text', delayMs: 0 },
  };
}

describe('fetch patch: review', () => {
  it('leaves a streamed request body unread for the real call', async () => {
    const { win, nativeFetch } = makeWin();
    const gate = createGate(200);
    gate.open({ mocks: [], settings });
    installFetchPatch(win, { gate, report: () => {}, now: () => 0 });

    const body = new ReadableStream({
      start(c) { c.enqueue(new TextEncoder().encode('chunk')); c.close(); },
    });
    const init = { method: 'POST', body, duplex: 'half' } as RequestInit;
    await win.fetch('https://app.test/api/upload', init);

    expect(nativeFetch).toHaveBeenCalledTimes(1);
    const passed = nativeFetch.mock.calls[0]![1] as RequestInit;
    expect((passed.body as ReadableStream).locked).toBe(false);
  });

  it('still serves the mock when report() throws', async () => {
    const { win, nativeFetch } = makeWin();
    const gate = createGate(200);
    gate.open({ mocks: [mockFor('/api/x')], settings });
    installFetchPatch(win, {
      gate,
      report: () => { throw new Error('postMessage failed'); },
      now: () => 0,
    });

    const res = await win.fetch('https://app.test/api/x');
    expect(await res.text()).toBe('mocked');
    expect(nativeFetch).not.toHaveBeenCalled();
  });

  it('resolves a relative string URL against the page, with a plain Request class', async () => {
    const { win } = makeWin();
    const gate = createGate(200);
    gate.open({ mocks: [mockFor('/api/rel')], settings });
    installFetchPatch(win, { gate, report: () => {}, now: () => 0 });
    const res = await win.fetch('/api/rel');
    expect(await res.text()).toBe('mocked');
  });
});

describe('fetch patch: review, round 2', () => {
  it('rejects with AbortError when the signal is aborted before the call, even for a mock', async () => {
    const { win, nativeFetch } = makeWin();
    const gate = createGate(200);
    gate.open({ mocks: [mockFor('/api/x')], settings });
    installFetchPatch(win, { gate, report: () => {}, now: () => 0 });
    const ac = new AbortController();
    ac.abort();
    await expect(win.fetch('https://app.test/api/x', { signal: ac.signal })).rejects.toMatchObject({
      name: 'AbortError',
    });
    expect(nativeFetch).not.toHaveBeenCalled();
  });

  it('logs the real response headers, lower-cased', async () => {
    const nativeFetch = vi.fn(async () =>
      new Response('{}', { headers: { 'Content-Type': 'application/json', 'X-Trace': 't1' } }));
    const win = { fetch: nativeFetch, Request, Response, Headers,
      location: { href: 'https://app.test/page' } } as unknown as Window;
    const gate = createGate(200);
    gate.open({ mocks: [], settings });
    const reported: unknown[] = [];
    installFetchPatch(win, { gate, report: (d) => reported.push(d), now: () => 0 });
    await win.fetch('https://app.test/api/real');
    await vi.waitFor(() => expect(reported).toHaveLength(1));
    expect(reported[0]).toMatchObject({
      badge: 'real',
      responseHeaders: { 'content-type': 'application/json', 'x-trace': 't1' },
    });
  });
});
